import{_ as a,o,c as i,j as e}from"./chunks/framework.44aEvdQQ.js";const m=JSON.parse(`{"title":"The Deployment That Didn't Require a Web App","description":"We needed to deploy without adding anything to the client's stack. Socket Mode and Railway made that possible for almost nothing.","frontmatter":{"title":"The Deployment That Didn't Require a Web App","date":"2026-02-11","series":"Infrastructure","description":"We needed to deploy without adding anything to the client's stack. Socket Mode and Railway made that possible for almost nothing.","sidebar":false,"prev":false,"next":false},"headers":[],"relativePath":"blog/03-socket-mode-railway.md","filePath":"blog/03-socket-mode-railway.md","blogPosts":[{"url":"/blog/21-not-everyone-works-forty-hours","fm":{"title":"Not Everyone Works Forty Hours","date":"2026-03-29","series":"Features","description":"Capacity planning only works if the system knows how each person actually works. VERA was treating your contractors like full-time employees. It no longer does."}},{"url":"/blog/20-when-done-means-done","fm":{"title":"When Done Means Done","date":"2026-03-25","series":"AI Behaviour","description":"A confirmation that nothing happened behind it is worse than no confirmation at all. We fixed the moment where trust breaks."}},{"url":"/blog/19-the-briefing","fm":{"title":"The Briefing That Replaced the Monday Check-in","date":"2026-03-24","series":"Features","description":"The morning summary now answers two questions simultaneously: what am I supposed to be working on, and where do my projects stand?"}},{"url":"/blog/18-sheets-formulas-as-code","fm":{"title":"Building the Dashboard the Owner Actually Needs","date":"2026-03-15","series":"Data Model","description":"A live dashboard that answers the real questions: which projects are healthy, which are at risk, and what the business earned this month."}},{"url":"/blog/17-two-spreadsheets","fm":{"title":"The Dashboard Is Always Current","date":"2026-03-13","series":"Architecture","description":"The client''s reporting view and the database are separate spreadsheets. The client can never accidentally break the data — and they never have to request a report."}},{"url":"/blog/16-column-order-is-the-api","fm":{"title":"The Invisible Contract in the Spreadsheet","date":"2026-03-12","series":"Data Model","description":"Google Sheets doesn''t enforce its own structure. We had to. The rules we built to keep the data trustworthy."}},{"url":"/blog/14-agile-as-billing-model","fm":{"title":"Agile as a Billing Model","date":"2026-03-08","series":"Business Logic","description":"A sprint is a delivery unit and a revenue recognition unit. Timeliness of logging determines timeliness of revenue — they''re the same thing."}},{"url":"/blog/15-ooo-is-a-financial-event","fm":{"title":"Absence Is Data Too","date":"2026-03-08","series":"Business Logic","description":"Time off is a cost. If it doesn''t appear in the same system as time worked, the capacity picture is wrong and the P&L is incomplete."}},{"url":"/blog/13-design-md-rethink","fm":{"title":"Writing It Down Made Us Confront What We''d Built","date":"2026-03-07","series":"Architecture","description":"Six weeks in, we stopped and wrote down every decision we''d made. Several of them turned out to be wrong."}},{"url":"/blog/12-phased-expansion","fm":{"title":"What Becomes Possible When the Data Is Real","date":"2026-03-03","series":"Features","description":"Once time tracking is accurate and timely, a layer of project intelligence that was previously impossible becomes straightforward."}},{"url":"/blog/11-multi-tenancy-bugs","fm":{"title":"Reliability Is the Promise","date":"2026-03-01","series":"Architecture","description":"Timeliness only works if the system is there when the moment arrives. Getting multi-tenant reliability right was non-negotiable."}},{"url":"/blog/10-multi-tenancy","fm":{"title":"Each Client Gets Their Own VERA","date":"2026-02-25","series":"Architecture","description":"Multi-tenancy wasn''t a feature request. It was the point. A tool that feels shared feels like someone else''s."}},{"url":"/blog/09-timebot-becomes-vera","fm":{"title":"TimeBot Becomes VERA","date":"2026-02-22","series":"Origins","description":"A name signals a relationship. We weren''t building a utility."}},{"url":"/blog/07-retainers-are-weird","fm":{"title":"Retainers Without Timely Data Are Just Guesses","date":"2026-02-19","series":"Business Logic","description":"A retainer is a commitment to deliver a volume of work within a period. If you don''t know where you are until the invoice, you''ve already lost."}},{"url":"/blog/08-snapshots-version-control-spreadsheet","fm":{"title":"The Business Was There Last Tuesday Too","date":"2026-02-19","series":"Infrastructure","description":"When data is live and timely, the next question is whether you can go back. We built that in from the start."}},{"url":"/blog/06-roles-and-dollars","fm":{"title":"The Data Is Only Worth Protecting If It''s Worth Something","date":"2026-02-17","series":"Permissions","description":"When the data is timely and accurate, the financial numbers become real. Real numbers need to reach the right people — and not the wrong ones."}},{"url":"/blog/04-schema-grows-up","fm":{"title":"Making a Slack Message Do the Work of a Form","date":"2026-02-12","series":"Data Model","description":"We removed the interface. That meant every piece of information the owner needed had to be captured from a casual Slack message without making that message any harder to send."}},{"url":"/blog/05-prompt-engineering-wars","fm":{"title":"The Clarifying Questions Problem","date":"2026-02-12","series":"AI Behaviour","description":"Timeliness is the whole product. Any friction that risks the timing is a product failure."}},{"url":"/blog/03-socket-mode-railway","fm":{"title":"The Deployment That Didn''t Require a Web App","date":"2026-02-11","series":"Infrastructure","description":"We needed to deploy without adding anything to the client''s stack. Socket Mode and Railway made that possible for almost nothing."}},{"url":"/blog/01-the-problem","fm":{"title":"The Problem That Made VERA Necessary","date":"2026-02-10","series":"Origins","description":"Every time tracking tool ever built starts from the wrong assumption. We found the one thing that fixes it."}},{"url":"/blog/02-day-one-slack-claude-sheets","fm":{"title":"Day One: Slack → Claude → Google Sheets","date":"2026-02-10","series":"Origins","description":"The three components we chose on day one — and why each one was chosen specifically because it required no new interface."}}]}`),s={name:"blog/03-socket-mode-railway.md"};function n(r,t,l,d,h,c){return o(),i("div",null,[...t[0]||(t[0]=[e("p",null,"One of the decisions we made early — and felt the benefit of immediately — was to never build a web app.",-1),e("p",null,"A web app would have meant a URL for the client to visit, a login to manage, a session to maintain, a UI to design and maintain and explain. It would have meant recreating the very ceremony we were trying to eliminate, just with a different front end.",-1),e("p",null,"Slack's Socket Mode is what made this possible to avoid. Instead of a public webhook URL that Slack pushes events to — which requires a server with a publicly accessible address, SSL certificates, DNS, the whole stack — Socket Mode opens a persistent outbound connection from the bot to Slack. No public URL. No incoming ports. The bot talks to Slack; Slack doesn't need to talk back to the bot.",-1),e("p",null,"That meant we could run the entire thing on Railway, a hosting platform that takes a Node process and runs it for a few dollars a month. No load balancers. No server configuration. No devops overhead. Push the code, it runs.",-1),e("hr",null,null,-1),e("p",null,"The cost matters here, but not for the reason you might expect. The reason it matters is that a cheap, simple deployment means we never needed to justify the infrastructure. There's no server to manage, no database to provision, no uptime SLA to worry about. The whole thing is a process that runs and connects to Slack and reads from Google Sheets.",-1),e("p",null,"Simplicity at the infrastructure level meant we could spend all of our time on the behaviour — on making VERA useful. Not on the plumbing.",-1),e("p",null,"The entire product, deployed and running for clients, costs less than a lunch every month. That's not a compromise. That's a design principle.",-1)])])}const p=a(s,[["render",n]]);export{m as __pageData,p as default};
